{
  "general": [
    {
      "type": "Procedure or Local Strategy",
      "title": "Open closed containers before placing inside",
      "principle": "If the destination is a closed container, open it before attempting to put the held object inside.",
      "when_to_apply": "When the destination is a cabinet, drawer, fridge, microwave, safe, or similar container and the observation indicates it is closed."
    },
    {
      "type": "Failure Lesson",
      "title": "Re-navigate after failed put",
      "principle": "If a put action returns 'Nothing happens', verify current location and navigate to the destination before retrying the put.",
      "why_it_happens": "The agent may have attempted to place an object without being at the destination location, causing the put action to fail silently.",
      "how_to_avoid": "After a failed put, check whether the agent is at the destination; if not, go to the destination and then retry the put."
    },
    {
      "type": "Failure Lesson",
      "title": "Avoid repeated failed actions and loops",
      "principle": "If an action fails (e.g., 'Nothing happens'), do not repeat it without changing state or approach; reassess and try a different action or location.",
      "why_it_happens": "The agent may get stuck repeating the same invalid action, wasting steps and leading to failure or handoff loops.",
      "how_to_avoid": "After a failed action, check inventory, location, and object states; try a different action or move to a different location."
    },
    {
      "type": "Failure Lesson",
      "title": "Verify object identity before pickup or transformation",
      "principle": "Ensure the object being picked up or transformed matches the target object type; similar but different objects (e.g., cup vs. mug, towel vs. handtowel) will not satisfy the goal.",
      "why_it_happens": "The agent may confuse similar objects or misread the observation, wasting time and causing task failure.",
      "how_to_avoid": "Read the observation carefully and confirm the object name matches the goal before taking or transforming it."
    },
    {
      "type": "Failure Lesson",
      "title": "Declare failure after exhaustive search",
      "principle": "If the target object cannot be found after searching relevant locations, declare failure rather than continuing indefinitely.",
      "why_it_happens": "The object may not exist in the environment or may be in an inaccessible location.",
      "how_to_avoid": "Search likely containers and surfaces; if the object is not found, report failure."
    }
  ],
  "task_specific": {
    "简单取放": [
      {
        "type": "Procedure or Local Strategy",
        "title": "Simple pick-and-place execution",
        "principle": "For simple pick-and-place tasks, locate the target object, take it, navigate to the destination, and put it down.",
        "when_to_apply": "When the goal is to move a single object to a specified destination and no cleaning, heating, cooling, or lighting is required."
      }
    ],
    "台灯观察": [
      {
        "type": "Procedure or Local Strategy",
        "title": "台灯观察：先定位台灯所在家具，再携带目标物前往",
        "principle": "在台灯观察任务中，不要直接尝试 go to desklamp；台灯是固定在家具上的对象，应先通过探索或已知位置找到承载台灯的家具（如 desk、sidetable、dresser、coffeetable），再携带目标物前往该家具并使用台灯。",
        "when_to_apply": "当目标物已取得或已在手，且需要将其置于台灯下观察时。"
      },
      {
        "type": "Procedure or Local Strategy",
        "title": "台灯观察：到达台灯所在家具后使用台灯完成观察",
        "principle": "携带目标物到达台灯所在家具后，执行 use desklamp 即可完成台灯观察；不需要对目标物执行 examine、use 或 look 来触发观察。",
        "when_to_apply": "当已携带目标物并位于台灯所在家具处，且任务要求 examine/look at 目标物 with/under the desklamp 时。"
      },
      {
        "type": "Failure Lesson",
        "title": "台灯观察：避免对目标物反复 examine/use/look 而不使用台灯",
        "principle": "在台灯观察任务中，反复对目标物执行 examine、use 或 look 通常不会触发成功条件；成功路径是到达台灯所在家具后使用台灯。若已尝试多次无效，应停止重复并转向寻找/使用台灯。",
        "when_to_apply": "当任务要求 look at/examine 目标物 under/with the desklamp，且对目标物直接 examine/use/look 返回 Nothing happens 或普通描述时。"
      },
      {
        "type": "Failure Lesson",
        "title": "台灯观察：不要尝试拿起或移动台灯",
        "principle": "台灯是固定对象，take desklamp 或 go to desklamp 通常无效；应把台灯视为家具上的固定交互点，通过前往其所在家具并使用它来完成观察。",
        "when_to_apply": "当任务涉及 desklamp，且尝试 take desklamp 或 go to desklamp 返回 Nothing happens 时。"
      }
    ],
    "清洗后放置": [
      {
        "type": "Procedure or Local Strategy",
        "title": "Clean-then-place sequence for 清洗后放置",
        "principle": "For clean-then-place goals, first acquire the target object, then go to a sinkbasin and clean it, then go to the destination and place it. If the destination is a closed container, open it before placing.",
        "when_to_apply": "When the goal is to put a clean object at a destination and the object is not already clean."
      },
      {
        "type": "Failure Lesson",
        "title": "Do not clean with non-sinkbasin fixtures",
        "principle": "Cleaning only works with a sinkbasin. Attempting to clean with a fridge, bathtubbasin, or other fixture produces 'Nothing happens' and wastes steps.",
        "when_to_apply": "When holding an object that needs cleaning and choosing a cleaning location."
      },
      {
        "type": "Failure Lesson",
        "title": "Do not place into non-receptacle fixtures",
        "principle": "Some fixtures such as toilets and coffeemachines are not valid placement receptacles. Repeated put attempts produce 'Nothing happens'; if the destination is invalid, report blocked rather than looping.",
        "when_to_apply": "When the destination is a toilet, coffeemachine, or other fixture that rejects placement."
      }
    ],
    "加热后放置": [
      {
        "type": "Procedure or Local Strategy",
        "title": "Heat held object directly with microwave",
        "principle": "When holding the target object and the microwave is open, use the direct heat action instead of placing the object inside first.",
        "when_to_apply": "Task type 加热后放置; target object is held; microwave is open; goal requires heating the object."
      },
      {
        "type": "Failure Lesson",
        "title": "Avoid repeated failed heating inside microwave",
        "principle": "Repeatedly using 'use microwave' or 'heat object with microwave' while the object is inside the microwave can fail without changing state.",
        "why_it_happens": "The environment may require the object to be held or the microwave to be open for the heat action to succeed.",
        "how_to_avoid": "If heating fails, take the object out, ensure the microwave is open, and try the direct heat action while holding the object."
      },
      {
        "type": "Failure Lesson",
        "title": "Open microwave before taking heated object",
        "principle": "After heating, taking the object from the microwave may fail if the microwave is closed or the object is not inside.",
        "why_it_happens": "The take action requires the object to be accessible inside an open microwave.",
        "how_to_avoid": "Open the microwave before attempting to take the heated object, and verify the object is inside."
      },
      {
        "type": "Procedure or Local Strategy",
        "title": "Place heated object at destination",
        "principle": "After heating and taking the object, go to the destination location and put the object there.",
        "when_to_apply": "Task type 加热后放置; object is heated and held; destination is known."
      }
    ],
    "冷却后放置": [
      {
        "type": "Procedure or Local Strategy",
        "title": "Cool held object with open fridge",
        "principle": "When the goal requires a cooled object, first acquire the object, then navigate to an open fridge while holding it, and use the cool command with the fridge.",
        "when_to_apply": "Holding the target object and standing at an open fridge, with the goal requiring the object to be cool."
      },
      {
        "type": "Failure Lesson",
        "title": "Do not cool by placing object in fridge",
        "principle": "Placing an object inside a fridge does not cool it; the cool command must be used while holding the object at the fridge.",
        "why_it_happens": "The environment only changes an object's temperature through the explicit cool action, not through containment.",
        "how_to_avoid": "After reaching the fridge with the object in hand, issue 'cool <object> with fridge' instead of putting the object into the fridge."
      },
      {
        "type": "Failure Lesson",
        "title": "Verify destination is open and reachable before placing",
        "principle": "A put action fails silently if the destination is closed or the agent is not at the destination; open the destination and navigate to it before placing.",
        "why_it_happens": "The environment requires the agent to be at an open receptacle to place an object.",
        "how_to_avoid": "After cooling, go to the destination, open it if closed, then put the held object there."
      },
      {
        "type": "Failure Lesson",
        "title": "Do not hand off before placing the cooled object",
        "principle": "Cooling the object is not sufficient; the task is complete only after the cooled object is placed at the required destination.",
        "why_it_happens": "The mission goal includes both cooling and placing, so declaring handoff after cooling alone leaves the task incomplete.",
        "how_to_avoid": "After cooling, continue to the destination and place the object before declaring success."
      }
    ],
    "双物品放置": [
      {
        "type": "Procedure or Local Strategy",
        "title": "Two-item placement: sequential pickup, transport, and placement",
        "principle": "For tasks requiring two identical or same-type objects to be placed at a destination, pick up one object, carry it to the destination, place it, then return for the second object and repeat.",
        "when_to_apply": "When the goal is to put two objects of the same type at a target location and the agent cannot hold both simultaneously."
      }
    ]
  }
}

